def span(path,a,b):
    lines=(ROOT/path).read_text(encoding='utf-8-sig').splitlines();assert 1<=a<=b<=len(lines)
    text='\n'.join(lines[a-1:b]);READS[(path,a,b)]=dict(path=path,start=a,end=b,selected_text_sha256=hashlib.sha256(text.encode()).hexdigest());return text
def literal(title,ids,pairs,predicate,description):
    t=[span(*x) for x in pairs];ok=bool(predicate(t));assert ok,title
